import csv
from typing import Optional


def column_mean(file_path: str, column_name: str) -> Optional[float]:
    """Return the mean of a numeric CSV column, ignoring missing values."""
    values = []

    with open(file_path, "r", newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)

        if not reader.fieldnames or column_name not in reader.fieldnames:
            raise ValueError(f"Column {column_name!r} not found")

        for row in reader:
            value = row[column_name].strip()
            if value and value.lower() not in {"na", "nan", "null", "none"}:
                try:
                    values.append(float(value))
                except ValueError:
                    raise ValueError(f"Non-numeric value in {column_name!r}: {value!r}")

    return sum(values) / len(values) if values else None
```

Missing entries are ignored. The function returns `None` if the column contains no numeric values.

```python
import csv
from statistics import fmean


def column_mean(file_path, column_name):
    """Return the mean of a CSV column, ignoring missing values."""
    missing = {"", "na", "n/a", "null", "none"}
    values = []

    with open(file_path, newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)

        if column_name not in (reader.fieldnames or []):
            raise ValueError(f"Column not found: {column_name}")

        for row in reader:
            value = row[column_name]
            if value is None or value.strip().lower() in missing:
                continue

            try:
                values.append(float(value))
            except ValueError as exc:
                raise ValueError(
                    f"Non-numeric value in column {column_name!r}: {value!r}"
                ) from exc

    if not values:
        raise ValueError(f"Column {column_name!r} has no numeric values")

    return fmean(values)
```

